  <script>
    const services = {
      wellness: { name: "वेलनेस जाँच", duration: 30, price: "₹600", exact: true, allowed: "any", api: "Wellness exam" },
      vaccine:  { name: "टीकाकरण विज़िट", duration: 15, price: "₹400", exact: true, allowed: "any", api: "Vaccination visit" },
      dental:   { name: "दाँतों की सफ़ाई", duration: 90, price: "₹3,500 से", exact: false, allowed: ["Mary Major"], api: "Dental cleaning" },
      exotic:   { name: "एक्ज़ॉटिक पेट जाँच", duration: 45, price: "₹900", exact: true, allowed: ["Mary Major"], api: "Exotic pet check-up" }
    };
    const vets = [
      { id: "Mary Major", name: "डॉ. मैरी मेजर", days: ["Tue", "Thu", "Sat"] },
      { id: "Richard Miles", name: "डॉ. रिचर्ड माइल्स", days: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"] }
    ];
    const apiSlots = [
      { vet: "Richard Miles", service: "Exotic pet check-up", start: "10:00" },
      { vet: "Mary Major", service: "Exotic pet check-up", start: "11:00" },
      { vet: "Mary Major", service: "Dental cleaning", start: "12:00" },
      { vet: "Richard Miles", service: "Wellness exam", start: "13:30" },
      { vet: "Richard Miles", service: "Wellness exam", start: "15:00" },
      { vet: "Mary Major", service: "Wellness exam", start: "16:45" }
    ];

    const mins = t => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
    const day = "Thu";
    function isBookable(slot) {
      const service = Object.values(services).find(s => s.api === slot.service);
      const vet = vets.find(v => v.id === slot.vet);
      if (!service || !vet || !vet.days.includes(day)) return false;
      if (service.allowed !== "any" && !service.allowed.includes(slot.vet)) return false;
      const start = mins(slot.start), end = start + service.duration;
      const withinClinic = start >= 9 * 60 && end <= 17 * 60;
      const overlapsLunch = start < 14 * 60 && end > 13 * 60;
      return withinClinic && !overlapsLunch;
    }
    const validSlots = apiSlots.filter(isBookable);

    let selectedService = null, selectedVet = null, selectedSlot = null;
    const $ = id => document.getElementById(id);
    const anyVet = "__any__";

    function updateSteps() {
      ["step1", "step2", "step3", "step4"].forEach((id, i) => {
        $(id).classList.toggle("current", i === (selectedService ? selectedVet ? selectedSlot ? 3 : 2 : 1 : 0));
        $(id).classList.toggle("done", [selectedService, selectedVet, selectedSlot, false][i]);
      });
    }
    function updateSummary() {
      const service = selectedService && services[selectedService];
      $("sumService").textContent = service ? service.name : "अभी चुनें";
      const vet = selectedSlot ? vets.find(v => v.id === selectedSlot.vet)?.name
        : selectedVet === anyVet ? "कोई भी उपलब्ध डॉक्टर"
        : vets.find(v => v.id === selectedVet)?.name || "अभी चुनें";
      $("sumDoctor").textContent = vet;
      $("sumTime").textContent = selectedSlot ? selectedSlot.start : "अभी चुनें";
      $("sumPrice").textContent = service ? service.price : "अभी चुनें";
      updateSteps();
    }
    function resetAfterService() {
      selectedVet = null; selectedSlot = null;
      $("slotSection").hidden = true;
      $("confirmSection").hidden = true;
      $("confirmMessage").textContent = "";
      $("doctorSection").hidden = false;
      renderDoctors();
      updateSummary();
    }
    document.querySelectorAll("[data-service]").forEach(button => {
      button.addEventListener("click", () => {
        selectedService = button.dataset.service;
        document.querySelectorAll("[data-service]").forEach(b =>
          b.setAttribute("aria-pressed", String(b === button)));
        $("dentalNote").hidden = selectedService !== "dental";
        resetAfterService();
      });
    });

    function eligibleVets() {
      const s = services[selectedService];
      return vets.filter(v => v.days.includes(day) &&
        (s.allowed === "any" || s.allowed.includes(v.id)));
    }
    function renderDoctors() {
      const box = $("doctorChoices");
      box.replaceChildren();
      const options = [{ id: anyVet, name: "कोई भी उपलब्ध डॉक्टर" }, ...eligibleVets()];
      options.forEach(vet => {
        const b = document.createElement("button");
        b.className = "choice";
        b.type = "button";
        b.setAttribute("aria-pressed", "false");
        b.innerHTML = `<strong>${vet.name}</strong><span class="hint">${
          vet.id === anyVet ? "इस सेवा के लिए उपलब्ध स्लॉट में से" : "गुरुवार को कार्यरत"
        }</span>`;
        b.addEventListener("click", () => {
          selectedVet = vet.id; selectedSlot = null;
          box.querySelectorAll("button").forEach(x =>
            x.setAttribute("aria-pressed", String(x === b)));
          $("confirmSection").hidden = true;
          $("confirmMessage").textContent = "";
          renderSlots();
          updateSummary();
        });
        box.append(b);
      });
    }
    function renderSlots() {
      $("slotSection").hidden = false;
      const box = $("slotChoices");
      box.replaceChildren();
      const s = services[selectedService];
      const matches = validSlots.filter(slot =>
        slot.service === s.api &&
        (selectedVet === anyVet || slot.vet === selectedVet)
      );
      $("emptySlots").hidden = matches.length > 0;
      $("emptySlots").textContent = "इस सेवा और डॉक्टर के लिए इस तारीख पर API ने कोई बुक करने योग्य स्लॉट नहीं लौटाया। दूसरी तारीख की उपलब्धता जाँचें।";
      matches.forEach(slot => {
        const vet = vets.find(v => v.id === slot.vet);
        const b = document.createElement("button");
        b.className = "slot"; b.type = "button";
        b.setAttribute("aria-pressed", "false");
        b.setAttribute("aria-label", `${slot.start} बजे, ${vet.name}`);
        b.innerHTML = `<strong>${slot.start}</strong><br><span class="hint">${vet.name}</span>`;
        b.addEventListener("click", () => {
          selectedSlot = slot;
          box.querySelectorAll("button").forEach(x =>
            x.setAttribute("aria-pressed", String(x === b)));
          $("confirmSection").hidden = false;
          $("confirmBtn").disabled = !s.exact;
          $("confirmMessage").textContent = s.exact ? "" : "सटीक अंतिम कीमत के बिना पुष्टि उपलब्ध नहीं है।";
          updateSummary();
        });
        box.append(b);
      });
    }
    $("confirmBtn").addEventListener("click", () => {
      if (!selectedSlot || !services[selectedService].exact) return;
      $("confirmMessage").textContent =
        "डेमो पुष्टि: गुरुवार, 18 जून 2026 · " + selectedSlot.start +
        " · " + vets.find(v => v.id === selectedSlot.vet).name +
        " · " + services[selectedService].name + " · " + services[selectedService].price +
        " · 12, गुलमोहर मार्ग, उदाहरणपुर";
      $("confirmMessage").className = "notice success";
    });
    updateSummary();
  </script>
